<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import { cancelMetaAdSetSync, getMetaAdSetSyncProgress, syncMetaAdSetFacts, type MetaAdSetSyncProgress, type MetaAdSetSyncResponse } from '@/api/dashboard'
import '@/styles/settings-notion.css'

interface Account { id: string; name: string; sub_account_id: string; status?: string }
const props = defineProps<{ show: boolean; connectionId: string; accounts: Account[]; currentAccountId?: string }>()
const emit = defineEmits<{ close: []; completed: [result: MetaAdSetSyncResponse] }>()
const searchInput = ref<HTMLInputElement | null>(null)
const search = ref('')
const selected = ref<string[]>([])
const since = ref('')
const until = ref('')
const stage = ref<'form' | 'syncing' | 'result'>('form')
const error = ref('')
const result = ref<MetaAdSetSyncResponse | null>(null)
const progress = ref<MetaAdSetSyncProgress>({ total: 0, completed: 0, succeeded: 0, failed: 0, running: 0, rows_written: 0, percent: 0 })
let activeController: AbortController | null = null
const total = computed(() => selected.value.length)
const activeAccounts = computed(() => props.accounts.filter(item => item.status === 'active' || !item.status))
const filtered = computed(() => { const q = search.value.trim().toLowerCase(); return activeAccounts.value.filter(item => !q || item.name.toLowerCase().includes(q) || item.sub_account_id.toLowerCase().includes(q)) })
const today = () => new Date().toISOString().slice(0, 10)
const reset = async () => { const end = new Date(); const start = new Date(end); start.setDate(start.getDate() - 29); since.value = start.toISOString().slice(0, 10); until.value = end.toISOString().slice(0, 10); selected.value = activeAccounts.value.map(item => item.sub_account_id.replace(/^act_/, '')); search.value = ''; stage.value = 'form'; error.value = ''; result.value = null; progress.value = { total: 0, completed: 0, succeeded: 0, failed: 0, running: 0, rows_written: 0, percent: 0 }; await nextTick(); searchInput.value?.focus() }
watch(() => props.show, value => { if (value) void reset() })
const toggle = (id: string) => { const index = selected.value.indexOf(id); if (index >= 0) selected.value.splice(index, 1); else selected.value.push(id) }
const dateError = computed(() => { if (!since.value || !until.value) return '请选择完整时间范围'; const days = (new Date(`${until.value}T00:00:00Z`).getTime() - new Date(`${since.value}T00:00:00Z`).getTime()) / 86400000 + 1; if (days < 1) return '开始日期不能晚于结束日期'; if (days > 31) return '单次同步最多 31 天'; return '' })
const canSubmit = computed(() => selected.value.length > 0 && !dateError.value)
const succeeded = computed(() => result.value?.accounts.filter(item => item.status === 'succeeded') ?? [])
const failed = computed(() => result.value?.accounts.filter(item => item.status === 'failed') ?? [])
const rows = computed(() => succeeded.value.reduce((sum, item) => sum + item.rows_written, 0))
const run = async () => { if (!canSubmit.value) return; stage.value = 'syncing'; error.value = ''; const request = { connection_id: props.connectionId, account_ids: [...selected.value], since: since.value, until: until.value }; const controller = new AbortController(); activeController = controller; progress.value = { total: selected.value.length, completed: 0, succeeded: 0, failed: 0, running: selected.value.length, rows_written: 0, percent: 0 }; const poll = async () => { try { progress.value = await getMetaAdSetSyncProgress(request) } catch { /* Main sync response owns error reporting. */ } }; const timer = window.setInterval(() => void poll(), 1000); try { result.value = await syncMetaAdSetFacts(request, controller.signal); await poll(); stage.value = 'result' } catch (e) { if (!controller.signal.aborted) error.value = e instanceof Error ? e.message : '数据同步失败，请稍后重试'; stage.value = 'form' } finally { window.clearInterval(timer); if (activeController === controller) activeController = null } }
const cancel = async () => { if (!activeController || stage.value !== 'syncing') return; const controller = activeController; const request = { connection_id: props.connectionId, account_ids: [...selected.value], since: since.value, until: until.value }; try { await cancelMetaAdSetSync(request) } finally { controller.abort(); activeController = null; stage.value = 'form'; error.value = '本次同步已停止，可以重新选择账号后再次同步' } }
const retry = () => { selected.value = failed.value.map(item => item.account_id); result.value = null; stage.value = 'form' }
const finish = () => { if (result.value) emit('completed', result.value); emit('close') }
const close = () => { if (stage.value !== 'syncing') emit('close') }
</script>

<template>
  <Teleport to="body">
    <div v-if="show" class="settings-modal-layer data-sync-layer" @click.self="close">
      <section class="settings-modal wide data-sync-modal" role="dialog" aria-modal="true" aria-labelledby="data-sync-title">
        <header class="settings-modal-head"><div><h2 id="data-sync-title">{{ stage === 'result' ? '数据同步结果' : '数据同步' }}</h2><p>{{ stage === 'form' ? '选择要更新的 Meta 广告账号和时间范围' : stage === 'syncing' ? '正在读取 Meta AdSet 日级数据，请保持页面打开' : '已按账号分别记录本次同步结果' }}</p></div><button class="settings-modal-close" type="button" aria-label="关闭" :disabled="stage === 'syncing'" @click="close"><span class="material-symbols-outlined">close</span></button></header>
        <div v-if="stage === 'form'" class="settings-modal-body data-sync-body">
          <section><div class="data-sync-heading"><h3>同步范围</h3><span>默认选择全部 {{ activeAccounts.length }} 个 active 账号</span></div><input ref="searchInput" v-model="search" class="sn-search" type="search" placeholder="搜索账号名称或 ID" aria-label="搜索账号" /><div class="data-sync-accounts"><label v-for="account in filtered" :key="account.id" :class="{ selected: selected.includes(account.sub_account_id.replace(/^act_/, '')) }"><input type="checkbox" :checked="selected.includes(account.sub_account_id.replace(/^act_/, ''))" @change="toggle(account.sub_account_id.replace(/^act_/, ''))" /><span><strong>{{ account.name }}</strong><small>{{ account.sub_account_id.replace(/^act_/, '') }}</small></span></label><div v-if="!filtered.length" class="data-sync-empty">没有可同步的 active 账号</div></div></section>
          <section class="data-sync-range"><div class="data-sync-heading"><h3>时间范围</h3><span>默认最近 30 天 · 最多 31 天</span></div><div class="data-sync-dates"><label>开始日期<input v-model="since" class="sn-input" type="date" /></label><label>结束日期<input v-model="until" class="sn-input" type="date" :max="today()" /></label></div><p v-if="dateError" class="sn-error">{{ dateError }}</p></section>
          <div class="data-sync-summary"><span class="material-symbols-outlined">info</span><p><strong>{{ total }} 个广告账号</strong> · {{ since }} 至 {{ until }} · 固定同步 <strong>AdSet 日级数据</strong></p></div><p v-if="error" class="sn-error" role="alert">{{ error }}</p>
        </div>
        <div v-else-if="stage === 'syncing'" class="settings-modal-body data-sync-progress" aria-live="polite"><span class="material-symbols-outlined data-sync-spinner">progress_activity</span><h3>已完成 {{ progress.completed }} / {{ progress.total }} 个广告账号</h3><div class="data-sync-progress-track" role="progressbar" aria-label="数据同步进度" :aria-valuenow="progress.percent" aria-valuemin="0" aria-valuemax="100"><i :style="{ width: `${progress.percent}%` }"></i></div><strong class="data-sync-progress-value">{{ progress.percent.toFixed(0) }}%</strong><p>成功 {{ progress.succeeded }} 个 · 失败 {{ progress.failed }} 个 · 已写入 {{ progress.rows_written }} 条 AdSet 日级事实</p><small>Meta 数据按 AdSet × 日期返回；后端正在按账号分页处理，请保持页面打开。</small></div>
        <div v-else class="settings-modal-body data-sync-body" aria-live="polite"><div class="data-sync-result" :class="{ partial: failed.length }"><span class="material-symbols-outlined">{{ failed.length ? 'warning' : 'check_circle' }}</span><div><strong>{{ failed.length ? '部分完成' : '同步完成' }}</strong><p>成功 {{ succeeded.length }} 个，失败 {{ failed.length }} 个，写入 {{ rows }} 条日级事实</p></div></div><div class="data-sync-result-list"><div v-for="item in result?.accounts" :key="item.account_id"><span class="material-symbols-outlined">{{ item.status === 'succeeded' ? 'check_circle' : 'error' }}</span><span><strong>{{ item.account_name || item.account_id }}</strong><small>{{ item.account_id }}</small></span><em>{{ item.status === 'succeeded' ? `${item.rows_written} 条` : item.message || '同步失败' }}</em></div></div></div>
        <footer class="settings-modal-actions"><template v-if="stage === 'form'"><button class="sn-button" type="button" @click="close">取消</button><button class="sn-button primary" type="button" :disabled="!canSubmit" @click="run"><span class="material-symbols-outlined">cloud_sync</span>开始同步</button></template><template v-else-if="stage === 'result'"><button v-if="failed.length" class="sn-button" type="button" @click="retry">重试失败账号</button><button class="sn-button primary" type="button" @click="finish">查看更新数据</button></template><template v-else><button class="sn-button danger" type="button" @click="cancel">停止同步</button><span class="data-sync-running">可以安全停止，已完成账号不会丢失</span></template></footer>
      </section>
    </div>
  </Teleport>
</template>

<style scoped>
.data-sync-modal { height:min(680px,calc(100dvh - 40px)); min-height:0; }.settings-modal-head p{margin:4px 0 0;color:var(--sn-steel);font-size:10px}.data-sync-body{display:grid;gap:18px}.data-sync-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px}.data-sync-heading h3{margin:0;color:var(--sn-ink);font-size:12px}.data-sync-heading span{color:var(--sn-stone);font-size:9px}.data-sync-accounts{max-height:260px;overflow:auto;border:1px solid var(--sn-line);border-radius:8px;margin-top:8px}.data-sync-accounts label{min-height:50px;display:grid;grid-template-columns:18px minmax(0,1fr);align-items:center;gap:10px;padding:7px 11px;border-bottom:1px solid var(--sn-line-soft);cursor:pointer}.data-sync-accounts label:last-of-type{border-bottom:0}.data-sync-accounts label.selected{background:var(--sn-surface-soft)}.data-sync-accounts label.disabled{opacity:.45;cursor:not-allowed}.data-sync-accounts strong,.data-sync-accounts small{display:block}.data-sync-accounts strong{font-size:11px;color:var(--sn-charcoal)}.data-sync-accounts small{margin-top:3px;color:var(--sn-stone);font-size:9px}.data-sync-empty{padding:28px;text-align:center;color:var(--sn-stone);font-size:10px}.data-sync-range{padding-top:17px;border-top:1px solid var(--sn-line-soft)}.data-sync-dates{display:grid;grid-template-columns:1fr 1fr;gap:10px}.data-sync-dates label{display:grid;gap:6px;color:var(--sn-slate);font-size:10px}.data-sync-dates input{margin-top:0}.data-sync-summary{display:flex;gap:8px;align-items:center;padding:10px;border-radius:7px;background:var(--sn-surface-soft);color:var(--sn-slate)}.data-sync-summary p{margin:0;font-size:10px}.data-sync-summary .material-symbols-outlined{font-size:17px}.data-sync-progress{display:grid;place-items:center;align-content:center;text-align:center}.data-sync-spinner{font-size:30px;color:var(--sn-blue);animation:data-sync-spin .8s linear infinite}.data-sync-progress h3{margin:12px 0 0;font-size:13px;color:var(--sn-ink)}.data-sync-progress-track{width:min(360px,80%);height:7px;margin:16px 0 6px;border-radius:99px;background:var(--sn-line-soft);overflow:hidden}.data-sync-progress-track i{display:block;height:100%;border-radius:inherit;background:var(--sn-blue);transition:width .2s ease}.data-sync-progress-value{color:var(--sn-blue);font-size:11px}.data-sync-progress p{max-width:420px;margin:10px 0 0;color:var(--sn-slate);font-size:10px;line-height:1.5}.data-sync-progress small{max-width:420px;margin-top:5px;color:var(--sn-stone);font-size:9px;line-height:1.5}.data-sync-result{display:flex;gap:10px;padding:13px;border-radius:8px;background:var(--sn-success-bg);color:var(--sn-success)}.data-sync-result.partial{background:var(--sn-warning-bg);color:var(--sn-warning)}.data-sync-result strong{font-size:12px}.data-sync-result p{margin:4px 0 0;color:var(--sn-slate);font-size:10px}.data-sync-result-list{border:1px solid var(--sn-line);border-radius:8px;overflow:hidden}.data-sync-result-list>div{min-height:52px;display:grid;grid-template-columns:20px minmax(0,1fr) auto;align-items:center;gap:9px;padding:8px 11px;border-bottom:1px solid var(--sn-line-soft)}.data-sync-result-list>div:last-child{border-bottom:0}.data-sync-result-list .material-symbols-outlined{font-size:18px;color:var(--sn-success)}.data-sync-result-list strong,.data-sync-result-list small{display:block}.data-sync-result-list strong{font-size:10px;color:var(--sn-charcoal)}.data-sync-result-list small{margin-top:2px;font-size:8px;color:var(--sn-stone)}.data-sync-result-list em{font-style:normal;font-size:9px;color:var(--sn-steel)}.data-sync-running{margin:auto;color:var(--sn-steel);font-size:10px}@keyframes data-sync-spin{to{transform:rotate(360deg)}}@media(max-width:520px){.data-sync-modal{height:calc(100dvh - 20px)}.data-sync-dates{grid-template-columns:1fr}}
</style>
